// OpenTUI (React) app for the screen "demo", generated by TUI Studio.
// Targets @opentui/core and @opentui/react 0.6.6 (React 19.2.0); needs Bun.
//
// Run:   bun install && bun run src/index.tsx
// Keys:  Tab / Shift+Tab move the focus, Enter or Space activate, q or Ctrl+C quit,
//        Ctrl+L shows the log panel, Esc closes a dialog.
//
// From your own program (see src/ui-runtime.tsx and PROGRAM_API.md):
//   import { Ui } from "./index";
//   const ui = new Ui();
//   await ui.start();                     // does not block
//   ui.status.hide();                       // states, properties and events of every code name
//   await ui.wait();
//
// Fill in the handler functions below; they are called by the components that name them.

