const pagesTabs = ["⌂ Dashboard", "Agent ● ^1", "QA Team ^2"];

// ── Program API ───────────────────────────────────────────────────────────────
// One typed handle per code name; `ui.<name>` below. Writing a property never fires an event.

class StatusHandle extends Handle {
  constructor(ui: UiCore) {
    super(ui, "status", "Text", ["active", "hidden"]);
  }
  get text(): string {
    return this._get("text") as string;
  }
  set text(value: string) {
    this._set("text", String(value));
  }
}

class NameInputHandle extends Handle {
  constructor(ui: UiCore) {
    super(ui, "name_input", "TextInput", ["active", "muted", "readonly", "hidden"]);
  }
  get value(): string {
    return this._get("value") as string;
  }
  set value(value: string) {
    this._set("value", String(value));
  }
  get placeholder(): string {
    return this._get("placeholder") as string;
  }
  set placeholder(value: string) {
    this._set("placeholder", String(value));
  }
  onChange(handler: UiHandler): () => void {
    return this._on("change", handler);
  }
  onSubmit(handler: UiHandler): () => void {
    return this._on("submit", handler);
  }
}

