export class Ui extends UiCore {
  readonly status: StatusHandle;
  readonly nameInput: NameInputHandle;
  readonly submitBtn: SubmitBtnHandle;
  readonly agree: AgreeHandle;
  readonly color: ColorHandle;
  readonly progress: ProgressHandle;
  readonly results: ResultsHandle;
  readonly files: FilesHandle;
  readonly pages: PagesHandle;
  readonly panel: PanelHandle;
  readonly inner: InnerHandle;
  readonly confirm: ConfirmHandle;
  constructor() {
    super();
    this.status = this.add(new StatusHandle(this), { state: "active", text: "Ready" });
    this.nameInput = this.add(new NameInputHandle(this), { state: "active", value: "", placeholder: "your name" });
    this.submitBtn = this.add(new SubmitBtnHandle(this), { state: "active", label: "Send" });
    this.agree = this.add(new AgreeHandle(this), { state: "active", checked: false, label: "I agree" });
    this.color = this.add(new ColorHandle(this), { state: "active", value: "Red", options: ["Red", "Green", "Blue"] });
    this.progress = this.add(new ProgressHandle(this), { state: "active", value: 0, max: 100 });
    this.results = this.add(new ResultsHandle(this), { state: "active", columns: ["Column 1", "Column 2"], rows: [["Cell 1", "Cell 2"], ["Cell 3", "Cell 4"]] });
    this.files = this.add(new FilesHandle(this), { state: "active", items: ["Item 1", "Item 2", "Item 3"], selected: 0 });
    this.pages = this.add(new PagesHandle(this), { state: "active", active_tab: 0 });
    this.panel = this.add(new PanelHandle(this), { state: "active" });
    this.inner = this.add(new InnerHandle(this), { state: "active", text: "Inside the panel" });
    this.confirm = this.add(new ConfirmHandle(this), { state: "active", title: "Sure?", open: false });
  }
  protected view(): ReactNode {
    return <App ui={this} />;
  }
}

type Hit = { x: number; y: number; scrollOffset?: number; setSelectedIndex?(index: number): void };
type MouseAt = { target: unknown; x: number; y: number; stopPropagation(): void };

/** The row of a list under the mouse, or -1 when the click was not on the list itself. */
function rowAt(event: MouseAt): number {
  const list = event.target as Hit | null;
  if (!list || typeof list.setSelectedIndex !== "function") return -1;
  return event.y - list.y + (list.scrollOffset ?? 0);
}

/** The tab under the mouse (tabs are `tabWidth` cells wide), or -1. */
function tabAt(event: MouseAt, tabWidth: number): number {
  const bar = event.target as Hit | null;
  if (!bar || typeof bar.setSelectedIndex !== "function") return -1;
  return Math.floor((event.x - bar.x) / tabWidth);
}

function select(event: MouseAt, index: number): void {
  (event.target as Hit).setSelectedIndex?.(index);
}

function toOptions(labels: string[], prefixes: string[] = []) {
  return labels.map((label, i) => ({ name: (prefixes[i] ?? "") + label, description: "", value: label }));
}

/** Header and rows of a table as aligned text lines (columns two cells apart). */
function tableLines(columns: string[], rows: string[][]): string[] {
  const count = Math.max(columns.length, ...rows.map((r) => r.length), 0);
  const cell = (r: string[], i: number) => r[i] ?? "";
  const widths = Array.from({ length: count }, (_, i) =>
    Math.max([...cell(columns, i)].length, ...rows.map((r) => [...cell(r, i)].length), 1)
  );
  const line = (r: string[]) =>
    widths.map((n, i) => cell(r, i) + " ".repeat(n - [...cell(r, i)].length)).join("  ");
  const head = columns.length ? [line(columns)] : [];
  return [...head, ...rows.map(line)];
}

function progressBar(value: number, max: number, width: number): string {
  const ratio = Math.max(0, Math.min(1, max > 0 ? value / max : 0));
  const filled = Math.round(ratio * Math.max(1, width - 5));
  const bar = "█".repeat(filled) + "░".repeat(Math.max(1, width - 5) - filled);
  return `${bar}${`${Math.round(ratio * 100)}%`.padStart(5)}`;
}

/** The line under a tab bar: `╸━━╺` below the active tab (` label ` cells), `━` elsewhere. */
function tabsRule(labels: string[], active: number): string {
  const cells = (l: string) => [...l].length + 2;
  const before = labels.slice(0, active).reduce((n, l) => n + cells(l), 0);
  const own = active >= labels.length ? 0 : cells(labels[active]);
  return "━".repeat(before) + (own >= 2 ? "╸" + "━".repeat(own - 2) + "╺" : "") + "━".repeat(500);
}

const SELECTS = new Set<string>(["color"]);
const TEXT_FIELDS = new Set<string>(["name_input"]);
const TABS = new Set<string>(["pages"]);

function App({ ui }: { ui: Ui }) {
  const sys = useSlice<{ dialog: unknown[]; scroll: number }>(ui, "$ui");
  // The open dropdown (one at a time) and its popup list.
  const [openSel, setOpenSel] = useState<{ id: string; up: boolean; x: number; y: number; w: number } | null>(null);
  const popRef = useRef<SelectRenderable | null>(null);
  useEffect(() => {
    setOpenSel(null);
  }, [sys.scroll]);
  const [focus, setFocus] = useState<string>("name_input");
  const statusS = useSlice<{ state: UiState; text: string }>(ui, "status");
  const nameInputS = useSlice<{ state: UiState; value: string; placeholder: string }>(ui, "name_input");
  const submitBtnS = useSlice<{ state: UiState; label: string }>(ui, "submit_btn");
  const agreeS = useSlice<{ state: UiState; checked: boolean; label: string }>(ui, "agree");
  const colorS = useSlice<{ state: UiState; value: string; options: string[] }>(ui, "color");
  const colorField = useRef<BoxRenderable | null>(null);
  const colorOpts = useMemo(() => toOptions(colorS.options), [colorS.options]);
  const progressS = useSlice<{ state: UiState; value: number; max: number }>(ui, "progress");
  const resultsS = useSlice<{ state: UiState; columns: string[]; rows: string[][] }>(ui, "results");
  const filesS = useSlice<{ state: UiState; items: string[]; selected: number }>(ui, "files");
  const filesOpts = useMemo(() => toOptions(filesS.items), [filesS.items]);
  const pagesS = useSlice<{ state: UiState; active_tab: number }>(ui, "pages");
  const panelS = useSlice<{ state: UiState }>(ui, "panel");
  const innerS = useSlice<{ state: UiState; text: string }>(ui, "inner");
  const confirmS = useSlice<{ state: UiState; title: string; open: boolean }>(ui, "confirm");

  const order = ([
    ["name_input", nameInputS.state === "active"],
    ["submit_btn", submitBtnS.state === "active"],
    ["agree", agreeS.state === "active"],
    ["color", colorS.state === "active"],
    ["files", filesS.state === "active"],
    ["pages", pagesS.state === "active"],
  ] as [string, boolean][])
    .filter(([, ok]) => ok)
    .map(([id]) => id);
  // Nothing has the focus while an error dialog is open.
  const focusId = sys.dialog.length === 0 && order.includes(focus) ? focus : "";

  const dd = openSel && order.includes(openSel.id) && sys.dialog.length === 0 ? openSel : null;
  ui.capture = dd !== null;

  const closeDropdown = () => setOpenSel(null);
  const openDropdown = (id: string) => {
    switch (id) {
      case "color":
        return setOpenSel({ id, up: (colorField.current?.y ?? 0) + 3 + Math.max(1, Math.min(colorS.options.length, 6)) + 2 > (ui.renderer?.height ?? 24), x: colorField.current?.x ?? 0, y: colorField.current?.y ?? 0, w: colorField.current?.width ?? 12 });
      default:
        break;
    }
  };
  const fieldClick = (id: string) => {
    if (ui.blocked || !order.includes(id)) return;
    setFocus(id);
    openDropdown(id);
  };
  const pick = (id: string, index: number) => {
    setOpenSel(null);
    switch (id) {
      case "color": {
        const value = colorS.options[index];
        if (value == null || ui.store.get("color").value === value) break;
        ui.store.patch("color", { value });
        ui.emit("color", "change", value, [handleChange]);
        break;
      }
      default:
        break;
    }
  };

  // Left and Right change the tab of a focused tab bar.
  const moveTab = (id: string, step: number) => {
    switch (id) {
      case "pages": {
        if (!ui.isActive("pages")) return;
        const next = Math.max(0, Math.min(3 - 1, pagesS.active_tab + step));
        if (pagesS.active_tab === next) return; ui.store.patch("pages", { active_tab: next }); ui.emit("pages", "change", next, []);
        return;
      }
      default:
        break;
    }
  };

  const move = (step: number) => {
    if (!order.length) return;
    const at = order.indexOf(focusId);
    setFocus(order[(at + step + order.length) % order.length]);
  };

  // Mouse: a click focuses and activates; nothing behind an error dialog reacts.
  const focusOn = (id: string) => {
    if (!ui.blocked && order.includes(id)) setFocus(id);
  };
  const click = (id: string) => {
    if (ui.blocked || !order.includes(id)) return;
    setFocus(id);
    activate(id);
  };

  const activate = (id: string) => {
    switch (id) {
      case "submit_btn":
        if (!ui.isActive("submit_btn")) break;
      ui.emit("submit_btn", "click", null, [handleClick]);
        break;
      case "agree": {
        if (!ui.isActive("agree")) break;
      const next = !agreeS.checked;
        ui.store.patch("agree", { checked: next });
        ui.emit("agree", "change", next, [handleChange]);
        break;
      }
      case "color":
        if (!ui.isActive("color")) break;
        openDropdown("color");
        break;
      default:
        break;
    }
  };

  // The popup lists are drawn by the runtime above the whole UI (and below error dialogs).
  const popups = (
    <>
      {dd?.id === "color" && (
        <box position="absolute" left={dd.x} top={dd.up ? dd.y - (Math.max(1, Math.min(colorS.options.length, 6)) + 2) : dd.y + 3} width={dd.w} height={Math.max(1, Math.min(colorS.options.length, 6)) + 2} zIndex={20} border borderStyle="single" backgroundColor="#000000" onMouseDown={(event: MouseAt) => { event.stopPropagation(); const i = rowAt(event); if (i >= 0 && i < colorS.options.length) pick("color", i); }}>
          <select ref={popRef} focused options={colorOpts} selectedIndex={Math.max(0, colorS.options.indexOf(colorS.value))} showDescription={false} flexGrow={1} onSelect={(index: number) => pick("color", index)} />
        </box>
      )}
    </>
  );
  useEffect(() => {
    ui.setOverlay(popups);
  });
  useEffect(() => () => ui.setOverlay(null), []);

  useKeyboard((key) => {
    if (dd && !key.ctrl) {
      // Up, Down and Enter are handled by the popup list itself.
      const list = popRef.current;
      if (key.name === "escape" || key.name === "tab") closeDropdown();
      else if (key.name === "space" || key.name === " ") pick(dd.id, list?.getSelectedIndex() ?? 0);
      else if (key.name === "home") list?.setSelectedIndex(0);
      else if (key.name === "end") list?.setSelectedIndex(Math.max(0, (list?.options.length ?? 1) - 1));
      return;
    }
    if (key.name === "down" && SELECTS.has(focusId)) return openDropdown(focusId);
    if (ui.handleKey(key)) return;
    if ((key.name === "left" || key.name === "right") && TABS.has(focusId)) return moveTab(focusId, key.name === "left" ? -1 : 1);
    if (key.name === "tab") return move(key.shift ? -1 : 1);
    if (TEXT_FIELDS.has(focusId)) return;
    if (key.name === "q") return ui.stop();
    if (key.name === "return" || key.name === "space" || key.name === " ") activate(focusId);
  });

  return (
          <box width="100%" minHeight="100%" onMouseDown={() => closeDropdown()} border borderStyle="single" borderColor="#f8f8f2" flexDirection="column" alignItems="flex-start" padding={1}>
            {statusS.state !== "hidden" && (
              <text flexShrink={0} fg="#f8f8f2" attributes={(statusS.state === "muted" ? TextAttributes.DIM : 0)} content={statusS.text} />
            )}
            {nameInputS.state !== "hidden" && (
              <box width={20} flexShrink={0} border borderStyle="single" borderColor="#f8f8f2" paddingLeft={2} onMouseDown={() => focusOn("name_input")}>
                <input flexGrow={1} value={nameInputS.value} placeholder={nameInputS.placeholder} textColor={nameInputS.state === "muted" ? "#808080" : "#f8f8f2"} focused={focusId === "name_input"} onInput={(value: string) => { if (!ui.isActive("name_input") || ui.store.get("name_input").value === value) return; ui.store.patch("name_input", { value }); ui.emit("name_input", "change", value, [handleChange]); }} onSubmit={(submitted: unknown) => { const value = typeof submitted === "string" ? submitted : nameInputS.value; ui.emit("name_input", "submit", value, []); }} />
              </box>
            )}
            {submitBtnS.state !== "hidden" && (
              <box flexShrink={0} border borderStyle="rounded" borderColor="#f8f8f2" minWidth={16} flexDirection="row" justifyContent="center" paddingLeft={1} paddingRight={1} onMouseDown={() => click("submit_btn")}>
                <text fg="#f8f8f2" attributes={TextAttributes.BOLD | (submitBtnS.state === "muted" ? TextAttributes.DIM : 0) | (focusId === "submit_btn" ? TextAttributes.INVERSE : 0)} content={submitBtnS.label} />
              </box>
            )}
            {agreeS.state !== "hidden" && (
              <text flexShrink={0} fg="#f8f8f2" attributes={(agreeS.state === "muted" ? TextAttributes.DIM : 0) | (focusId === "agree" ? TextAttributes.INVERSE : 0)} content={(agreeS.checked ? "[✓] " : "[ ] ") + agreeS.label} onMouseDown={() => click("agree")} />
            )}
            {colorS.state !== "hidden" && (
              <box width="100%" flexShrink={0} border borderStyle="single" borderColor="#f8f8f2" flexDirection="row" justifyContent="space-between" paddingLeft={2} paddingRight={2} ref={colorField} onMouseDown={(event: MouseAt) => { event.stopPropagation(); fieldClick("color"); }}>
                <text fg="#f8f8f2" attributes={(colorS.state === "muted" ? TextAttributes.DIM : 0) | (focusId === "color" ? TextAttributes.INVERSE : 0)} content={colorS.value} />
                <text fg="#f8f8f2" attributes={(colorS.state === "muted" ? TextAttributes.DIM : 0) | (focusId === "color" ? TextAttributes.INVERSE : 0)} content="▼" />
              </box>
            )}
            {progressS.state !== "hidden" && (
              <box width={20} flexShrink={0} border borderStyle="single" borderColor="#f8f8f2">
                <text flexGrow={1} fg="#f8f8f2" attributes={(progressS.state === "muted" ? TextAttributes.DIM : 0)} content={progressBar(progressS.value, progressS.max, 18)} />
              </box>
            )}
            {resultsS.state !== "hidden" && (
              <box flexShrink={0} border borderStyle="single" borderColor="#f8f8f2" flexDirection="column" paddingLeft={1} paddingRight={1}>
                {tableLines(resultsS.columns, resultsS.rows).map((line, i) => (
                  <text key={i} fg="#f8f8f2" attributes={(resultsS.state === "muted" ? TextAttributes.DIM : 0) | (i === 0 && resultsS.columns.length ? TextAttributes.BOLD : 0)} content={line} />
                ))}
              </box>
            )}
            {filesS.state !== "hidden" && (
              <box width="100%" flexShrink={0} border borderStyle="single" borderColor="#f8f8f2" onMouseDown={(event: MouseAt) => { focusOn("files"); if (ui.blocked || !ui.isActive("files")) return; const i = rowAt(event); if (i < 0 || i >= filesS.items.length) return; select(event, i); ui.store.patch("files", { selected: i }); ui.emit("files", "select", i, [handleSelect]); }}>
                <select height={3} flexGrow={1} showDescription={false} showSelectionIndicator={false} marginLeft={-1} options={filesOpts} selectedIndex={filesS.selected} onChange={(index: number) => { if (focusId !== "files") return; if (ui.store.get("files").selected !== index) ui.store.patch("files", { selected: index }); }} onSelect={(index: number) => { if (focusId !== "files") return; ui.store.patch("files", { selected: index }); ui.emit("files", "select", index, [handleSelect]); }} focused={focusId === "files"} textColor={filesS.state === "muted" ? "#808080" : "#f8f8f2"} />
                <text position="absolute" left={-1} top={0} fg="#f8f8f2" content={"│\n│\n│"} />
              </box>
            )}
            {pagesS.state !== "hidden" && (
              <box width="100%" height={2} flexShrink={0} flexDirection="column">
                <box flexDirection="row" height={1} flexShrink={0}>
                  {pagesTabs.map((label, i) => (
                    <text key={i} fg="#f8f8f2" attributes={(pagesS.state === "muted" ? TextAttributes.DIM : 0) | (i === pagesS.active_tab ? TextAttributes.BOLD : 0) | (i === pagesS.active_tab && focusId === "pages" ? TextAttributes.INVERSE : 0)} content={` ${label} `} onMouseDown={() => { focusOn("pages"); if (ui.blocked || !ui.isActive("pages")) return; if (pagesS.active_tab === i) return; ui.store.patch("pages", { active_tab: i }); ui.emit("pages", "change", i, []); }} />
                  ))}
                </box>
                <box height={1} width="100%" overflow="hidden" flexShrink={0}>
                  <text fg="#f8f8f2" content={tabsRule(pagesTabs, pagesS.active_tab)} />
                </box>
              </box>
            )}
            {panelS.state !== "hidden" && (
              <box flexShrink={0} border borderStyle="single" borderColor="#f8f8f2" flexDirection="column" gap={1} alignItems="flex-start" padding={1}>
                {innerS.state !== "hidden" && (
                  <text flexShrink={0} fg="#f8f8f2" attributes={(innerS.state === "muted" ? TextAttributes.DIM : 0)} content={innerS.text} />
                )}
              </box>
            )}
            {confirmS.open && confirmS.state !== "hidden" && (
              <box position="absolute" left={20} top={6} zIndex={10} width={40} height={12} flexShrink={0} border borderStyle="double" borderColor="#f8f8f2" title={confirmS.title} titleAlignment="center" backgroundColor="#21222c" flexDirection="column" alignItems="flex-start" padding={2}>
                <text flexShrink={0} fg="#f8f8f2" content={"Really?"} />
              </box>
            )}
          </box>
  );
}

// Started directly (bun run src/index.tsx): show the UI until it is closed.
if ((import.meta as { main?: boolean }).main) {
  const ui = new Ui();
  await ui.start();
  await ui.wait();
  (globalThis as { process?: { exit(code?: number): void } }).process?.exit(0);
}
